import type { FC, MutableRefObject } from 'react';
import { Bar } from 'react-chartjs-2';

import type { Chart, ChartData, ChartOptions, Plugin } from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { ChartHeader, ChartWrapper, ComparisonLine, Legend } from 'components';
import {
  ExtendYAxisPlugin,
  MissingDataBarPlugin,
  ZeroLabelPlugin,
} from 'components/Chart/Bar/SimpleBarChart/plugins';
import { ConnectorPlugin } from 'components/Chart/plugins';
import { ChartTooltipContent } from 'pages/components';

import {
  POS_CHART_CANVAS_HEIGHT_PX,
  POS_COMPARISON_GRID_INSET_OFFSET_PX,
  POS_COMPARISON_GRID_PAD_LEFT_PX,
  POS_COMPARISON_GRID_PAD_RIGHT_PX,
} from './constants';
import {
  StyledChartCanvasWrapper,
  StyledChartPlotWrapper,
  StyledComparisonLineWrapper,
  StyledHeaderWrapper,
  StyledPosChartBleedLine,
  StyledPosChartBleedLineX,
  StyledPosChartBleedShell,
} from './PosPerformance.styles';
import type {
  PosPerformanceChartData,
  PosPerformanceTableRow,
} from './types/index';
import { mapComparisonLineRows } from './utils';

type BleedLines = {
  yZero: number;
  yBottom: number;
};

export interface PosPerformanceChartViewProps {
  chartData: PosPerformanceChartData;
  dataTestId?: string;
  chartRef: MutableRefObject<Chart<'bar'> | null>;
  shellRef: MutableRefObject<HTMLDivElement | null>;
  bleedLines: BleedLines | null;
  barChartJsData: ChartData<'bar'>;
  options: ChartOptions<'bar'>;
  posBarSpacingPlugin: Plugin<'bar'>;
  bleedSyncPlugin: Plugin<'bar'>;
  labels: string[];
  comparisonRows: PosPerformanceTableRow[];
}

export const PosPerformanceChartView: FC<PosPerformanceChartViewProps> = ({
  chartData,
  dataTestId,
  chartRef,
  shellRef,
  bleedLines,
  barChartJsData,
  options,
  posBarSpacingPlugin,
  bleedSyncPlugin,
  labels,
  comparisonRows,
}) => {
  return (
    <ChartWrapper
      dataTestId={
        dataTestId ? `${dataTestId}-pos-performance-chart-wrapper` : undefined
      }
      header={
        <StyledHeaderWrapper>
          <ChartHeader
            title={chartData.chartTitle}
            measure={chartData.measure}
            config={{
              inline: 'horizontal',
              type: 'large',
              alignment: 'left',
            }}
            tooltipSize="medium"
            dataTestId={
              dataTestId
                ? `${dataTestId}-pos-performance-chart-header`
                : 'pos-performance-chart-header'
            }
            info={
              <ChartTooltipContent
                title={chartData.chartHeaderTooltip.title}
                subtitle={chartData.chartHeaderTooltip.subtitle}
                text={chartData.chartHeaderTooltip.text}
                paddingLeft={false}
              />
            }
          />
        </StyledHeaderWrapper>
      }
    >
      <Legend
        caption={chartData.legend}
        legendPosition="center"
        fontSize="xsmall"
        dataTestId={
          dataTestId
            ? `${dataTestId}-pos-performance-legend`
            : 'pos-performance-legend'
        }
      />
      <StyledPosChartBleedShell
        ref={shellRef}
        $height={POS_CHART_CANVAS_HEIGHT_PX}
      >
        {bleedLines ? (
          <>
            <StyledPosChartBleedLineX aria-hidden $top={bleedLines.yZero} />
            <StyledPosChartBleedLine aria-hidden $top={bleedLines.yBottom} />
          </>
        ) : null}
        <StyledChartPlotWrapper>
          <StyledChartCanvasWrapper>
            <Bar
              ref={chartRef}
              data={barChartJsData}
              options={options}
              plugins={[
                posBarSpacingPlugin,
                bleedSyncPlugin,
                ConnectorPlugin,
                ChartDataLabels,
                ZeroLabelPlugin,
                ExtendYAxisPlugin,
                MissingDataBarPlugin,
              ]}
            />
          </StyledChartCanvasWrapper>
        </StyledChartPlotWrapper>
      </StyledPosChartBleedShell>
      <StyledComparisonLineWrapper>
        <ComparisonLine
          dataTestId={
            dataTestId
              ? `${dataTestId}-pos-performance-comparison-line`
              : 'pos-performance-comparison-line'
          }
          data={mapComparisonLineRows(comparisonRows)}
          gridColumnsLength={labels.length}
          gridConfig={{
            paddingLeft:
              POS_COMPARISON_GRID_PAD_LEFT_PX -
              POS_COMPARISON_GRID_INSET_OFFSET_PX,
            paddingRight:
              POS_COMPARISON_GRID_PAD_RIGHT_PX -
              POS_COMPARISON_GRID_INSET_OFFSET_PX,
          }}
        />
      </StyledComparisonLineWrapper>
    </ChartWrapper>
  );
};
